"""Charts (tables) for Bava Kamma 1, 2, 4, 6 mishnayot that have no SVG. Run after write_bk_1_2.py and write_bk_4_6.py. Content only from the mishnah, Kulp and Kehati."""
import json
C = {
 1: {3: {"title": "Assessing damages", "cols": ["What", "The rule"], "rows": [["Where", "before a court (of experts)"], ["Witnesses", "free and Jewish"], ["Who may sue", "women as well as men"], ["Half damages", "the injured and the injurer share the loss"]]}},
 2: {1: {"title": "The foot (and fowl)", "cols": ["What happened", "What the owner pays"], "rows": [["Walked in its usual way and broke an object", "full damages"], ["Kicked, or stones were tossed from under its feet", "half damages"], ["Broke a vessel, which fell and broke another", "full for the first, half for the other"], ["Fowl broke something in its usual way", "full damages"], ["Fowl with entangled feet, or jumping", "half damages"]]},
     3: {"title": "Dogs and goats", "cols": ["What happened", "What the owner pays"], "rows": [["Jumped from a roof and broke vessels", "full damages"], ["Took a cake with an ember, burned a stack of grain", "full for the cake, half for the stack"]]},
     4: {"title": "How an animal changes status", "cols": ["", "Becomes an attested danger", "Harmless again"], "rows": [["Rabbi Judah", "testimony on three days", "three days without damage"], ["Rabbi Meir", "testimony three times", "children can touch it and it does not gore"], ["Halakha", "like Rabbi Judah", "like Rabbi Meir"]]},
     6: {"title": "A person who damages", "cols": ["Payment", "When"], "rows": [["Damage (nezek): full damages", "always: accident or on purpose, awake or asleep"], ["Pain, healing, loss of time, shame (chapter 8)", "only if deliberate or nearly so"]]}},
 4: {1: {"title": "Three oxen injured in turn (each worth 200; Kulp's table)", "cols": ["", "Owner of the injuring ox keeps", "First ox", "Second ox", "Third ox"], "rows": [["Rabbi Meir", "0", "0", "100", "100"], ["Rabbi Shimon", "25", "25", "50", "100"]]},
     2: {"title": "Full or half damages", "cols": ["The ox is an attested danger", "Not an attested danger", "The owner pays"], "rows": [["to its own kind", "to other kinds", "full for the first, half for the second"], ["to people", "to beasts", "full for the first, half for the second"], ["to children", "to adults", "full for the first, half for the second"], ["on the Sabbath (Rabbi Judah)", "during the week", "full on Sabbaths, half on weekdays"]]},
     4: {"title": "Whose ox, whose ox", "cols": ["Whose ox gored", "Whose ox was gored", "The owner of the goring ox"], "rows": [["a person of sound senses", "a deaf-mute, person with psychosis or minor", "pays"], ["a deaf-mute, person with psychosis or minor", "a person of sound senses", "exempt"]]},
     5: {"title": "An ox that kills a person", "cols": ["Victim", "Harmless ox", "Attested danger"], "rows": [["A free adult, a son or a daughter", "ox stoned; no ransom", "ox stoned; owner pays ransom"], ["A slave or maidservant", "ox stoned; owner pays 30 sela", "ox stoned; owner pays 30 sela"]]},
     6: {"title": "The ox's intention", "cols": ["The ox", "Result"], "rows": [["rubbed against a wall that fell on a person", "exempt from death"], ["intended to kill an animal and killed a man", "exempt from death"], ["intended to kill a gentile and killed an Israelite", "exempt from death"], ["intended to kill an untimely birth and killed a viable infant", "exempt from death"]]},
     8: {"title": "An ox sentenced to stoning", "cols": ["", "Dedicated to the Temple", "Slaughtered"], "rows": [["After the sentence is complete", "not dedicated", "flesh forbidden"], ["Before the sentence is complete", "dedicated", "flesh permitted"]]},
     9: {"title": "A tied or locked ox that got out and damaged", "cols": ["Rabbi Meir", "Rabbi Judah", "Rabbi Eliezer"], "rows": [["liable, harmless or attested danger", "harmless: liable; attested danger: exempt", "its only guarding is the knife"]]}},
 6: {1: {"title": "A flock gets out", "cols": ["What happened", "The owner"], "rows": [["Shut in properly and it went out and damaged", "exempt"], ["Not shut in properly", "liable"], ["The pen broke at night, or bandits broke it", "not liable"], ["Bandits brought out the flock", "the bandits are liable"]]},
     2: {"title": "The flock and the owner", "cols": ["What happened", "The owner pays"], "rows": [["Left in the sun, or given to a deaf-mute, person with psychosis or minor", "liable"], ["Fell into a garden and benefited", "what it benefited"], ["Went down into the garden in its usual way", "the damage"]]},
     5: {"title": "What was in the burned stack", "cols": ["What burned", "Rabbi Judah", "The Sages"], "rows": [["Utensils inside a stack", "pays for them too", "pays only for the wheat or barley"], ["A large building with goods in it", "pays for everything", "pays for everything (all agree)"], ["A kid fastened to the stack, a slave nearby; both burned", "liable", "liable"], ["A slave fastened to the stack, a kid nearby; both burned", "not liable", "not liable"]]},
     6: {"title": "Sparks and lamps", "cols": ["What happened", "Who pays"], "rows": [["A spark flew from under the hammer", "the one who struck"], ["A camel's flax went into a shop and caught the shopkeeper's light", "the owner of the camel"], ["The shopkeeper had left his light outside", "the shopkeeper"], ["A Hanukkah light (Rabbi Judah)", "not liable; the halakha does not follow him"]]}}}
for ch, d in C.items():
    p = f"data/bava_kamma_{ch}_layer1.json"; L = json.load(open(p))
    for m in L["mishnayot"]:
        if m["n"] in d: m["chart"] = d[m["n"]]
    json.dump(L, open(p, "w"), ensure_ascii=False, indent=1)
print("charts added")
